#![allow(unsafe_code, reason = "Exercise JNI FFI and native method exports.")]
#![allow(missing_docs, reason = "Executable examples and test fixtures are not library API.")]
#![cfg(feature = "invocation")]
//! Tests that it's possible to register native methods that are used within
//! static initializers in Java classes.
//!
//! For this to work the `<Type>API::get` method that's generated by the
//! `bind_java_type!` macro must avoid triggering the static initializer before
//! registering the native methods.
//!
mod bind_native_methods_utils;
mod util;

use abos_jni::objects::JClass;
use abos_jni::sys::jint;
use abos_jni::{Env, bind_java_type};
use rusty_fork::rusty_fork_test;

bind_java_type! {
	rust_type = TestNativeStaticInit,
	java_type = "com.example.TestNativeStaticInit",
	methods {
		static fn get_static_value() -> jint,
	},
	native_methods {
		static fn native_initialize_static(jint) -> jint,
	}
}
impl TestNativeStaticInitNativeInterface for TestNativeStaticInitAPI {
	type Error = abos_jni::errors::Error;

	fn native_initialize_static<'local>(
		_env: &mut Env<'local>,
		_class: JClass<'local>,
		value: jint,
	) -> Result<jint, Self::Error> {
		Ok(value + 27)
	}
}

native_method_test! {
	test_name: test_native_method_in_static_initializer,
	java_class: "com/example/TestNativeStaticInit.java",
	api: TestNativeStaticInitAPI,
	test_body: |env| {
		// The static initializer will have to run before we can call get_static_value

		let static_value = TestNativeStaticInit::get_static_value(env)?;
		assert_eq!(static_value, 42, "Static value should 5 + 10 + 27 = 42");

		// redundantly re-get the API to ensure the static init does not somehow run again
		let _ = TestNativeStaticInitAPI::get(env, &abos_jni::refs::LoaderContext::default())?;

		let static_value = TestNativeStaticInit::get_static_value(env)?;
		assert_eq!(static_value, 42, "Static value should still be 42");

		Ok(())
	}
}

rusty_fork_test! {
	#[test]
	fn test_native_method_in_static_initializer_from_worker() {
		let fixtures: std::path::PathBuf = util::java_fixtures();
		util::attach_current_thread(|env| {
			util::load_test_class(env, &fixtures, "TestNativeStaticInit")
		})
		.expect("define class without initializing it");

		std::thread::spawn(|| {
			util::attach_current_thread(|env| {
				let thread: abos_jni::objects::JThread<'_> = abos_jni::objects::JThread::current_thread(env)?;
				thread.set_context_class_loader(env, abos_jni::objects::JClassLoader::null())?;

				// A null context loader cannot find the application class. The fallback
				// must leave it uninitialized until the API registers its native method.
				let class: JClass<'_> = abos_jni::refs::LoaderContext::None.load_class_for_type::<TestNativeStaticInit>(env, false)?;
				assert!(!class.is_null());
				let static_value: jint = TestNativeStaticInit::get_static_value(env)?;
				assert_eq!(static_value, 42);
				Ok(())
			})
			.expect("register natives before initializing the class on a worker");
		})
		.join()
		.expect("worker succeeds");
	}
}
